import{_ as l,l as i,o as a,c as d,v as t,p as n,x as r,d as s,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"Bw-tree","description":"","frontmatter":{"title":"Bw-tree","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bw-tree.md","filePath":"cs/bw-tree.md","lastUpdated":1789023840000}'),h={name:"cs/bw-tree.md"};function B(A,e,_,E,m,S){const o=i("Mermaid");return a(),d("div",null,[e[1]||(e[1]=t('<h1 id="bw-tree" tabindex="-1">Bw-tree <a class="header-anchor" href="#bw-tree" aria-label="Permalink to &quot;Bw-tree&quot;">​</a></h1><div class="epigraph"><p>逻辑页是映射表里的指针：原地改换成 delta 记录链，CAS 安装新地址；结构修改也走无闩路径。</p><footer>—— 据 Levandoski, Lomet and Sengupta, The Bw-Tree, ICDE 2013；B-link 对照</footer></div><p><a href="/cs/latch-crabbing">上一课</a>在页闩上蟹行。本课不持写闩走满节点。缺口是主存优化索引：多核上 latch 仍是缓存行争用。Bw-tree 把「页」变成映射表（page id → 地址），更新用单字 CAS 挂 delta，读方沿着 delta 链看到最新逻辑页。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统 B+：改槽要写闩，叶热点（递增键）把核排队。Bw-tree：插入是分配 delta 记录（键+载荷），CAS 把映射表从旧页地址改到「delta→旧页」。失败则重试。缺口是<strong>无闩并不无同步</strong>，同步在 CAS 与 epoch 回收。</p><p>链太长则 consolidate：把 delta 与基页合成新基页，再 CAS 安装。分裂/合并是安装新页 id 并改父，用 SMO 协议保证读者看到一致。闪存/持久化变体另说；原论文面向主存+日志。</p><p><span class="marginnote">Levandoski, Lomet, Sengupta, ICDE 2013，微软 Hekaton 相关。ART 下一课是另一主存索引族（基数树）。本课不把 Bw 当磁盘 B+ 的替代教条。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找：映射表取地址，沿 delta 链+基页二分或扫描。范围：逻辑叶有序，链上有插入删除。GC：epoch 或类似，确保无读者还在旧地址上才回收。崩溃：映射表与页要进 WAL 或检查点，比纯内存结构重。</p><p>与缓冲池：逻辑页可能不在固定帧模型里；主存库常自己分配。磁盘库用 Bw 要重新设计落盘，本课点名边界。</p>',10)),(a(),n(c,null,{default:r(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PID%5B%22page%20id%22%5D%20--%3E%20MAP%5B%22%E6%98%A0%E5%B0%84%E8%A1%A8%20CAS%22%5D%0A%20%20MAP%20--%3E%20D%5B%22delta%20%E8%AE%B0%E5%BD%95%22%5D%0A%20%20D%20--%3E%20BASE%5B%22%E5%9F%BA%E9%A1%B5%22%5D%0A%20%20D%20--%3E%20CONS%5B%22%E9%93%BE%E9%95%BF%E5%88%99%E5%90%88%E5%B9%B6%E6%96%B0%E5%9F%BA%E9%A1%B5%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正确性：读者看到的链是某次 CAS 前缀，不会撕裂槽。隔离仍要事务层（锁或 MVCC 版本在载荷里）。Bw 只替换页闩这一层。</p><p>与 LRU-K 无关若页不进经典池。混合引擎可能叶在 Bw、溢出在磁盘 B+——实现复杂性高。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 ART 的 Node4/16/48/256。也不把无锁跳表当 Bw。学习索引更后。</p><p>后课默认：高并发主存点查可用映射+delta 减少写闩。ART 在数据库：字节序范围扫描的自适应基数树，常作主存主索引。</p><p>无闩索引把争用从锁管理器挪到 CAS 与回收，不取消事务语义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Bw-tree 用映射表与 delta CAS 更新逻辑页。</li><li>链合并与 SMO 仍要协议；GC 用 epoch。</li><li>ART 在数据库下一课：有序主存索引的另一形状。</li><li>出处：Levandoski, Lomet, Sengupta, ICDE 2013；B-link 对照。</li></ul>',9))])}const T=l(h,[["render",B]]);export{C as __pageData,T as default};
